ee:message.ee:set-payload:
%dw 2.0
output application/json
var response = payload.Envelope.Body.Consulta_detalle_inventarioResponse.Consulta_detalle_inventarioResult
---
{
    consultInventoryDetailOutput: {
      wsResponseHeader: {
        system: {
          correlationId: vars.correlationId,
          name: "MULESOFT",
          processingServer: "MULESOFT"
        },
        service: {
          responseDate: vars.responseDate,
          status: "PASS"
        }
      },
      bodyResponse: {
        consult_inventory_detailResponse: {
          inventory_actions: response.accion_inventario.*'Scheme_Services.PS_ACCION_INVENTARIO' map ((item, index) -> {
inventory_action: {
    quantity: item.cantidad as Number,
    final_state: item.estado_final,
    initial_state: item.estado_inicial,
    provisioning_id: item.id_aprovisionamiento,
    final_state_id: item.id_estado_final,
    initial_state_id: item.id_estado_inicial,
    action_type_id: item.id_tipo_accion,
    observation: item.observacion,
    action_type: item.tipo_accion
}
          }),
          inventory_attributes: response.atributos_inventario.*'Scheme_Services.PS_ATRIBUTO_INVENTARIO' map ((item, index) -> {
inventory_attribute: {
    description: item.descripcion,
    attribute_id: item.id_atributo,
    name: item.nombre,
    order: item.orden as Number,
    data_type: item.tipo_dato,
    value: item.valor
}
          }),
          cellar: response.bodega,
          quantity: response.cantidad as Number,
          reservation_quantity: response.cantidad_reserva as Number,
          cost_center: response.centro_costo,
          appreciation_class: response.clase_valoracion,
          document: response.documento,
          is_active: response.es_activo as Boolean default null,
          state: response.estado,
          up_date: response.fecha_alta,
          cellar_id: response.id_bodega,
          state_id: response.id_estado,
          product_id: response.id_producto,
          batch: response.lote,
          client_nit: response.nit_cliente,
          position: response.posicion,
          product: response.producto,
          serial: response.serial,
          ubication: response.ubicacion,
          unit_value: response.valor_unitario as Number
        }
      }
    }
}
